package com.bank.leadingdigit;

import java.util.*;
import java.util.logging.*;

public class LeadingDigitDemo {
    private static final Logger log = Logger.getLogger("LeadingDigit");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> accounts = List.of(1001, 2500, 150, 199, 3000, 1);
        LeadingDigitService service = new LeadingDigitService();

        log.info(() -> "Starting with '1': " + service.startingWith(accounts, '1'));
    }
}

// ─── Would be in service/LeadingDigitService.java ───
class LeadingDigitService {
    List<Integer> startingWith(List<Integer> nums, char digit) {
        String prefix = String.valueOf(digit);
        return nums.stream()
            .filter(n -> String.valueOf(n).startsWith(prefix))  // leading-digit match
            .toList();
    }
}
